package com.cpf.batch.centercut.runner; import com.cpf.batch.centercut.runner.internal.*; import com.cpf.batch.runtime.LogContext; import com.cpf.batch.spi.CenterCutHandler; import org.springframework.stereotype.Component; import java.util.*;
@Component public class CenterCutDispatcher { private final JdbcCenterCutClaimRepository repo;private final Map<String,CenterCutHandler> handlers;public CenterCutDispatcher(JdbcCenterCutClaimRepository r,List<CenterCutHandler> list){repo=r;Map<String,CenterCutHandler> m=new HashMap<>();for(CenterCutHandler h:list)if(m.put(h.handlerKey(),h)!=null)throw new IllegalStateException("Duplicate handler");handlers=Map.copyOf(m);} public void execute(JdbcCenterCutClaimRepository.Claim c){var w=repo.load(c);CenterCutHandler h=handlers.get(w.handlerKey());if(h==null){repo.complete(c,"FAILED",null,"Approved handler not found: "+w.handlerKey());return;}try(LogContext ignored=LogContext.open(Map.of("transactionId",Objects.toString(w.transactionId(),""),"segmentId",Objects.toString(w.segmentId(),""),"executionId",w.centerCutJobId(),"jobId",w.jobCode()))){var r=h.handle(new CenterCutHandler.Context(w.jobCode(),w.itemId(),w.businessKey(),w.payload(),w.transactionId(),w.segmentId(),c.fencingToken()));String s=switch(r.status().toUpperCase(Locale.ROOT)){case "SUCCESS","COMPLETED"->"SUCCESS";case "UNKNOWN","UNKNOWN_RESULT"->"UNKNOWN_RESULT";default->r.retryable()?"RETRY":"FAILED";};repo.complete(c,s,r.payload(),r.message());}catch(Exception e){repo.complete(c,"UNKNOWN_RESULT",null,e.getMessage());}} }
